import { useId } from "react";
import type { AdRatio } from "@/lib/strategyShowcase";

const SIZE: Record<AdRatio, { h: number; s: number; head: number; fs: number }> = {
  "1:1": { h: 400, s: 0.86, head: 0.15, fs: 28 },
  "4:5": { h: 500, s: 1, head: 0.15, fs: 30 },
  "9:16": { h: 711, s: 1.22, head: 0.14, fs: 34 },
};

/**
 * A static ad for the fictional brand "Aurel Skin", drawn as SVG so it stays crisp
 * at any size. Used only as an illustration of Creative Strategy's output format —
 * it is not generated by the product and is always shown with an illustration label.
 */
export function AdMock({ ratio, lines, cta, className = "" }: { ratio: AdRatio; lines: [string, string]; cta: string; className?: string }) {
  const uid = useId().replace(/:/g, "");
  const { h, s, head, fs } = SIZE[ratio];
  const cx = 200;
  const by = h * 0.6; // bottle centre
  const bw = 92 * s;
  const bh = 150 * s;
  return (
    <svg viewBox={`0 0 400 ${h}`} className={`block h-auto w-full ${className}`} role="img" aria-label={`Illustrative ${ratio} ad: ${lines.join(" ")}`}>
      <defs>
        <linearGradient id={`bg${uid}`} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor="#F7EDE1" />
          <stop offset="1" stopColor="#EFCDAE" />
        </linearGradient>
        <linearGradient id={`gl${uid}`} x1="0" y1="0" x2="1" y2="0">
          <stop offset="0" stopColor="#B9651F" />
          <stop offset="0.45" stopColor="#E19A4E" />
          <stop offset="1" stopColor="#A9581A" />
        </linearGradient>
        <radialGradient id={`sun${uid}`} cx="0.5" cy="0.5" r="0.5">
          <stop offset="0" stopColor="#F9C98C" stopOpacity="0.9" />
          <stop offset="1" stopColor="#F9C98C" stopOpacity="0" />
        </radialGradient>
      </defs>
      <rect width="400" height={h} fill={`url(#bg${uid})`} />
      <circle cx={cx} cy={by} r={150 * s} fill={`url(#sun${uid})`} />
      <text x="26" y="40" fontSize="17" fontWeight="700" letterSpacing="2" fill="#3B2416" fontFamily="inherit">
        AUREL
      </text>
      <text x={cx} y={h * head + 18} textAnchor="middle" fontSize={fs} fontWeight="700" fill="#2E1C12" fontFamily="inherit">
        {lines[0]}
      </text>
      <text x={cx} y={h * head + 18 + fs * 1.18} textAnchor="middle" fontSize={fs} fontWeight="700" fill="#2E1C12" fontFamily="inherit">
        {lines[1]}
      </text>
      {/* dropper bottle */}
      <g>
        <ellipse cx={cx} cy={by + bh / 2 + 6 * s} rx={bw * 0.62} ry={9 * s} fill="#3B2416" opacity="0.14" />
        <rect x={cx - 13 * s} y={by - bh / 2 - 58 * s} width={26 * s} height={40 * s} rx={12 * s} fill="#2B1B12" />
        <rect x={cx - 17 * s} y={by - bh / 2 - 22 * s} width={34 * s} height={24 * s} rx={5 * s} fill="#3A271B" />
        <rect x={cx - bw / 2} y={by - bh / 2} width={bw} height={bh} rx={22 * s} fill={`url(#gl${uid})`} />
        <rect x={cx - bw / 2 + 9 * s} y={by - bh / 2 + 12 * s} width={6 * s} height={bh - 30 * s} rx={3 * s} fill="#fff" opacity="0.28" />
        <rect x={cx - 34 * s} y={by - 26 * s} width={68 * s} height={60 * s} rx={6 * s} fill="#F7EDE1" />
        <text x={cx} y={by - 2 * s} textAnchor="middle" fontSize={12 * s} fontWeight="800" letterSpacing={1.5 * s} fill="#3B2416" fontFamily="inherit">
          AUREL
        </text>
        <text x={cx} y={by + 15 * s} textAnchor="middle" fontSize={8 * s} fontWeight="600" letterSpacing={1 * s} fill="#8A5A36" fontFamily="inherit">
          VITAMIN C
        </text>
        <path
          d={`M ${cx + bw / 2 + 26 * s} ${by - 40 * s} q ${9 * s} ${14 * s} 0 ${22 * s} q ${-9 * s} ${-8 * s} 0 ${-22 * s} z`}
          fill="#E19A4E"
        />
      </g>
      <rect x={cx - 70} y={h - 70} width="140" height="40" rx="20" fill="#2E1C12" />
      <text x={cx} y={h - 45} textAnchor="middle" fontSize="15" fontWeight="600" fill="#fff" fontFamily="inherit">
        {cta}
      </text>
    </svg>
  );
}
